parameters.expression:
=if ($json.linkedinPostUrl == null || $json.linkedinPostUrl == '') {
  throw new Error('LinkedIn Post URL is required');
}

return {
  url: $json.linkedinPostUrl,
  timestamp: new Date().toISOString(),
  batchSize: $json.batchSize || 100
};

nodes.parameters:
id": "7",
      "name": "Enrich Profile Data",
      "type": "n8n-nodes-base.httpRequest",
      "typeVersion": 4.1,
      "position": [1250, 300],
      "retryOptions": {
        "maxRetries": 2,
        "delayMultiplier": 2,
        "initialDelay": 500
      },
      "notesInFlow": true,
      "notes": "Enrich each profile with additional data - handles individual failures",
      "credentials": {
        "httpHeaderAuth": "linkedin-api-credentials"
      }
    },
    {
      "parameters": {
        "mode": "internal",
        "expression": "={
  name: $json.name || 'Unknown',
  email: $json.email || '',
  workplace: $json.workplace || $json.company || '',
  title: $json.title || $json.headline || '',
  location: $json.location || '',
  enriched: $json.name != null,
  timestamp: new Date().toISOString(),
  profile_id: $json.profile_id
};"
      },
      "id": "8",
      "name": "Transform Profile Data",
      "type": "n8n-nodes-base.code",
      "typeVersion": 2,
      "position": [1450, 300],
      "notesInFlow": true,
      "notes": "Transform enriched data into standardized format"
    },
    {
      "parameters": {
        "operation": "filter",
        "node": "Transform Profile Data",
        "value": "={{ $json.email != '' && $json.email != null }}",
        "combineOperation": "AND"
      },
      "id": "9",
      "name": "Filter - Only Profiles with Email",
      "type": "n8n-nodes-base.filter",
      "typeVersion": 2,
      "position": [1650, 200],
      "notesInFlow": true,
      "notes": "Keep only profiles with email addresses"
    },
    {
      "parameters": {
        "operation": "filter",
        "node": "Transform Profile Data",
        "value": "={{ $json.email == '' || $json.email == null }}",
        "combineOperation": "AND"
      },
      "id": "10",
      "name": "Filter - Profiles without Email",
      "type": "n8n-nodes-base.filter",
      "typeVersion": 2,
      "position": [1650, 400],
      "notesInFlow": true,
      "notes": "Keep profiles without email for separate tracking"
    },
    {
      "parameters": {
        "authentication": "oAuth2",
        "operation": "append",
        "spreadsheetId": "{{ $credentials.spreadsheetId }}",
        "range": "Sheet1!A:G",
        "values": "=[
  ["{{ $json.name }}", "{{ $json.email }}", "{{ $json.workplace }}", "{{ $json.title }}", "{{ $json.location }}", "{{ $json.profile_id }}", "{{ $json.timestamp }}"]
]"
      },
      "id": "11",
      "name": "Append to Google Sheets (With Email)",
      "type": "n8n-nodes-base.googleSheets",
      "typeVersion": 4,
      "position": [1850, 200],
      "notesInFlow": true,
      "notes": "Add profiles with email to main sheet",
      "credentials": {
        "googleSheetsOAuth2": "google-sheets-credentials"
      }
    },
    {
      "parameters": {
        "authentication": "oAuth2",
        "operation": "append",
        "spreadsheetId": "{{ $credentials.spreadsheetId }}",
        "range": "NoEmail!A:G",
        "values": "=[
  ["{{ $json.name }}", "N/A", "{{ $json.workplace }}", "{{ $json.title }}", "{{ $json.location }}", "{{ $json.profile_id }}", "{{ $json.timestamp }}"]
]"
      },
      "id": "12",
      "name": "Append to Google Sheets (No Email)",
      "type": "n8n-nodes-base.googleSheets",
      "typeVersion": 4,
      "position": [1850, 400],
      "notesInFlow": true,
      "notes": "Add profiles without email to separate 'NoEmail' sheet",
      "credentials": {
        "googleSheetsOAuth2": "google-sheets-credentials"
      }
    },
    {
      "parameters": {
        "mode": "internal",
        "expression": "={
  status: 'success',
  message: 'LinkedIn post enrichment completed',
  summary: {
    total_processed: $node['Calculate Statistics'].json.total,
    with_email: $node['Calculate Statistics'].json.withEmail,
    without_email: $node['Calculate Statistics'].json.withoutEmail,
    timestamp: new Date().toISOString()
  }
};"
      },
      "id": "13",
      "name": "Success Response",
      "type": "n8n-nodes-base.code",
      "typeVersion": 2,
      "position": [2050, 300],
      "notesInFlow": true,
      "notes": "Generate success response with processing statistics"
    }
  ],
  "connections": {
